const express = require('express');
const app = express();

app.get('/square/:n', (req, res) => {
  const n = Number(req.params.n);
  if (!Number.isInteger(n)) {
    return res.status(400).json({ error: 'n must be an integer' });
  }
  res.json({ n, square: n * n });
});

app.listen(8026);

module.exports = app;

