const http = require('http');
const assert = require('assert');
require('./server.js');
function get(p) { return new Promise((res, rej) => {
  http.get({host: '127.0.0.1', port: 8026, path: p}, r => {
    let b = ''; r.on('data', d => b += d); r.on('end', () => res({status: r.statusCode, body: b}));
  }).on('error', rej);
}); }
(async () => {
  await new Promise(r => setTimeout(r, 500));
  let r = await get('/square/4');
  assert.strictEqual(r.status, 200);
  const j = JSON.parse(r.body);
  assert.strictEqual(j.n, 4);
  assert.strictEqual(j.square, 16);
  r = await get('/square/abc');
  assert.strictEqual(r.status, 400);
  assert('error' in JSON.parse(r.body));
  console.log('PASS');
  process.exit(0);
})().catch(e => { console.error(e); process.exit(1); });
